#include "OutputMatrixEngine.h"
#include <array>
#include <bit>
#include <cstdlib>
#include <iostream>
#include <vector>
namespace { void check(bool v,const char*m){if(!v){std::cerr<<"FAIL: "<<m<<'\n';std::exit(1);}} struct Block{std::array<std::vector<double>,16>in,out;std::array<const double*,16>ip{};std::array<double*,16>op{};EntropyAudioBlockF64 abi{};Block(unsigned n){for(unsigned c=0;c<16;++c){in[c].resize(n);out[c].resize(n);ip[c]=in[c].data();op[c]=out[c].data();}abi.struct_size=sizeof(abi);abi.input_channels=16;abi.output_channels=16;abi.frames=n;abi.inputs=ip.data();abi.outputs=op.data();}};}
int main(){entropy::output_matrix::OutputMatrixEngine e;check(!e.prepare(96000,64),"96 kHz accepted");check(e.prepare(192000,64),"192 kHz rejected");EntropyOutputMatrixState s{};s.struct_size=sizeof(s);s.generation=9;s.active_source_mask=(1u<<0)|(1u<<1)|(1u<<2)|(1u<<5);s.enabled_destination_mask=(1u<<3)|(1u<<7);s.source_destination_mask[0]=1u<<3;s.source_destination_mask[1]=1u<<7;s.source_destination_mask[2]=1u<<7;s.source_destination_mask[5]=1u<<12;check(e.setState(s)==ENTROPY_OK,"state rejected");Block b(64);for(unsigned c=0;c<16;++c)for(unsigned f=0;f<64;++f)b.in[c][f]=std::bit_cast<double>(0x3fd0000000000000ULL+c*1024+f);check(e.process(b.abi)==ENTROPY_OK,"process failed");for(unsigned f=0;f<64;++f){check(std::bit_cast<std::uint64_t>(b.out[3][f])==std::bit_cast<std::uint64_t>(b.in[0][f]),"identity changed");check(b.out[7][f]==b.in[1][f]+b.in[2][f],"sum failed");for(unsigned d=0;d<16;++d)if(d!=3&&d!=7)check(b.out[d][f]==0.0,"unrouted not silent");}auto t=e.telemetry();check(t.applied_generation==9&&t.active_destination_mask==((1u<<3)|(1u<<7)),"active telemetry");check(t.summing_destination_mask==(1u<<7)&&t.orphaned_source_mask==(1u<<5),"sum/orphan telemetry");check(t.route_count==3&&t.host_engine_rate==192000&&t.processed_frames==64,"route/rate telemetry");std::cout<<"PASS strict FP64/192 routing, identity, summing detection, orphan fail-safe\n";}
